mapper.insert:
INSERT INTO TB_WEATHER_ALERT (
    ALERT_DATE, ALERT_TYPE, ALERT_LEVEL, ALERT_CMD,
    REGION_NM, REGION_CD, PARENT_REGION, ISSUE_DT, EFFECT_DT
) VALUES (
    TRUNC(SYSDATE), #{alertType}, #{alertLevel}, #{alertCmd},
    #{regionNm}, #{regionCd}, #{parentRegion}, #{issueDt}, #{effectDt}
)

INSERT INTO TB_WEATHER_RISK (
    RISK_DATE, REGION_CD, REGION_NM, DISTRICT_NM,
    WEATHER_SCORE, APPLIED_ALERTS, WILDFIRE_SCORE, WILDFIRE_GRADE, WILDFIRE_TM
) VALUES (
    TRUNC(SYSDATE), #{regionCd}, #{regionNm}, #{districtNm},
    #{weatherScore}, #{appliedAlerts}, #{wildfireScore}, #{wildfireGrade}, #{wildfireTm}
)
